{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 공영주차장에서 임산부가 주차요금 할인을 받을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제7조제1항제7호의3에 따라, 「서울특별시 임산부 예우 및 지원에 관한 조례」에 따른 임산부가 탑승한 차량은 주차요금의 100분의 50을 할인받을 수 있습니다. 다만, 임산부임을 증명할 수 있는 서류를 제시해야 합니다.",
          "b_ids": "주차장:제7조제1항제7호의3"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "공영주차장 임산부 할인 적용 시 제시해야 하는 증빙서류 또는 확인 방법",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "임산부 할인은 임산부임을 증명할 수 있는 서류를 제시해야 적용됩니다. 구체적으로는 「서울특별시 임산부 예우 및 지원에 관한 조례」에 따른 임산부 앱카드 등 임산부임을 증명할 수 있는 서류를 제시하면 됩니다. 또한 주차시간측정계기 또는 바로녹색결제시스템으로 각 호의 자격이 확인되는 주차장 이용자는 증빙서류를 제시하지 않고 주차요금을 감면받을 수 있습니다.",
          "b_ids": "주차장:제7조제1항, 주차장:제7조제1항제7호의3"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
